import{_ as o,o as c,c as d,a5 as p}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"对props的双向绑定","description":"双向绑定也就是 v model 的值必须是以下值之一： reactive 值 ; ref 值 ; 有 get 和 set 方法的计算属性；计算属性的依赖基不能由 props ，否则我们在 set 方法中就必须修改 props 值，这与 props 单身流动相冲突；但如果这个值确实。","frontmatter":{"title":"对props的双向绑定","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","模板、组件与交互"],"description":"双向绑定也就是 v model 的值必须是以下值之一： reactive 值 ; ref 值 ; 有 get 和 set 方法的计算属性；计算属性的依赖基不能由 props ，否则我们在 set 方法中就必须修改 props 值，这与 props 单身流动相冲突；但如果这个值确实。","sidebarWeight":100,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/组件/对props的双向绑定.md"},"headers":[],"relativePath":"posts/Vue系统教程/02-模板、组件与交互/对props的双向绑定.md","filePath":"posts/Vue系统教程/02-模板、组件与交互/对props的双向绑定.md"}'),r={name:"posts/Vue系统教程/02-模板、组件与交互/对props的双向绑定.md"};function s(t,e,a,i,l,_){return c(),d("div",null,[...e[0]||(e[0]=[p('<div><h1 id="对props的双向绑定" tabindex="-1">对props的双向绑定 <a class="header-anchor" href="#对props的双向绑定" aria-label="Permalink to &quot;对props的双向绑定&quot;">​</a></h1><blockquote><p>本节目标：理解“对props的双向绑定”的核心思路，并能把它用于实际开发或面试表达。 双向绑定也就是<code>v-model</code>的值必须是以下值之一：</p></blockquote><ul><li><code>reactive</code>值<code>;</code></li><li><code>ref</code>值<code>;</code></li><li>有<code>get</code>和<code>set</code>方法的计算属性；计算属性的依赖基不能由<code>props</code>，否则我们在<code>set</code>方法中就必须修改<code>props</code>值，这与<code>props</code>单身流动相冲突；但如果这个值确实和<code>props</code>值相关，我们应该是由<code>props</code>直接在<code>create</code>阶段计算得到一个<code>reactive</code>或<code>ref</code>值，这个计算属性<code>get</code>中的依赖值是这个<code>reactive</code>或<code>ref</code>值。</li><li>总之就是一个可以修改的响应式值；</li></ul><p><code>Props</code>的值有时我们不止是用于展示，我们还想对它进行修改； 比如在表单元素中；</p><p>如果<code>props</code>的某个属性值是对象或数组类型； 我们在组件中想修改它的元素；</p><p>如果将<code>props.propsName</code>直接进行赋值，<code>vue</code>会提示不许可，保持<code>props</code>的单向流动； 但如果我们只是修改<code>propName</code>这个对象的属性，<code>vue</code>目前是许可的，但并不推荐，除非它们是强耦合的；</p><p><strong>数组</strong> 如果属性值是一个数组，我们要对数组进行增删改；</p><ul><li>这个时候，应该根据属性值返回一个新数组，注意不是通过计算属性实现；</li><li>根据属性值得到的计算属性是无法修改的，没法双向绑定；</li><li>以这个新数组为初始值，定义一个<code>state</code>或<code>ref</code>值，这样，我们就可以对这个值进行修改了，并做到双向绑定；</li><li>并且不会修改<code>props</code>原数组；但如果数组的元素是一个对象，我们修改它的属性值，也会间接影响到原<code>props</code>数组；</li><li>如果<code>props</code>数组发生改变，由于不是响应式的，由<code>props</code>创建新数组的过程只在<code>setup</code>中发生，<code>props</code>变化时不会发生，所以我们<code>state</code>或<code>ref</code>的值并不再受<code>props</code>影响；</li><li>接下来，我们对计算得来的<code>State</code>或<code>ref</code>值进行双向绑定，或者进一步，可根据需要，由<code>state</code>或<code>ref</code>得到一个计算属性，对这个计算属性进行双向绑定；</li><li>总结来说就是，<code>props</code>直接计算一个<code>State</code>或<code>ref</code>值，对这个值进行双向绑定；或由这个计算出的<code>state</code>或<code>ref</code>值得出一个计算属性，对这个计算属性进行双向绑定；</li></ul><p>这就是官网说的，由根据<code>props</code>定义一个计算属性； 所不同的时，如果是计算属性，<code>props</code>变化，计算属性值也会变化； 并且，我们无法对这个计算属性值进行修改；从而也不会修改<code>props</code>，但这无法满足业务中对<code>props</code>值要进行修改的场景；</p></div>',1)])])}const f=o(r,[["render",s]]);export{u as __pageData,f as default};
